shots.draw_js:
clearScene();setBig(null);setEq(null);
mdpChain({n:7,y:290,r:26,x:230,gap:130,
  label:function(i){return "s"+(i+1);},
  cls:function(i){return "b";}});
note("前四讲的全部状态",640,382,"b");
note("Atari 一屏：10⁵⁰ 以上",640,430,"r");
setCap("前四讲的每一条保证，都建立在<b>一个能列举完的状态表</b>上。");

clearScene();setEq(null);
setBig("只是换个存法","压缩一下表而已，算法没变");
setCap("「用函数代替表」听起来像存储优化 —— <b>算法一个字都没改</b>。");

clearScene();setBig(null);
setEq("$$\\hat V(s;w)=x(s)^{\\top}w \\qquad x(s)\\in\\mathbb{R}^d$$","top");
note("d 个参数覆盖全部状态",640,300,"b lg");
note("表格 = one-hot 特征",640,360,"y lg");
setCap("表格<b>也是</b>线性逼近 —— 它取的特征恰好是 one-hot。");

clearScene();setBig(null);
setEq("$$\\Delta w \\propto x(s) \\;\\Longrightarrow\\; \\Delta \\hat V(s') \\propto x(s')^{\\top}x(s)$$","top");
note("特征重叠 = 互相影响",640,300,"r lg");
note("one-hot 时内积为 0",640,360,"g lg");
setCap("更新状态 s，别的状态跟着变 —— 变多少由<b>特征内积</b>决定。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"表格",sub:"不泛化 · 不干扰",state:"on"},
  {label:"函数逼近",sub:"泛化 = 干扰",state:"on"},
  {label:"两者",sub:"同一个内积",state:"on"}]});
note("前四讲用的是那个 0",640,420,"r");
setCap("<b>指名反驳</b>：不是换个存法，是把「更新互不影响」这条性质<b>拿掉了</b>。");

clearScene();setBig(null);
setEq("$$\\text{oracle}: \\ (s_1,V^{\\pi}(s_1)),\\ (s_2,V^{\\pi}(s_2)),\\ \\ldots$$","top");
note("这就是一个回归问题",640,310,"g lg");
setCap("先假装有个神谕，把 <b>(状态, 真值)</b> 成对交给你。那你会怎么做？");

clearScene();setEq(null);
setBig("这得是套新算法","值函数逼近听起来自成一体");
setCap("名字很唬人，但底下<b>只有一条式子</b>，而且是最普通的那条。");

clearScene();setBig(null);
setEq("$$J(w)=\\mathbb{E}_{d}\\Big[\\big(V^{\\pi}(s)-\\hat V(s;w)\\big)^2\\Big]$$","top");
note("期望按 d(s) 取",640,300,"y lg");
note("这个下标是伏笔",640,360,"r lg");
setCap("目标函数是均方误差。<b>但它对哪个分布取期望？</b>这一点第四集专讲。");

clearScene();setBig(null);
setEq("$$\\Delta w=\\alpha\\big(V^{\\pi}(s)-x(s)^{\\top}w\\big)\\,x(s)$$","top");
note("梯度塌成特征本身",640,310,"g lg");
setCap("线性逼近下 ∇V̂ = x(s)，于是<b>整条更新式里只剩特征</b>。");

clearScene();setBig(null);setEq(null);
note("误差",360,290,"r lg");
note("× 特征",640,290,"b lg");
note("× 步长",900,290,"y lg");
setCap("<b>指名反驳</b>：没有新算法。整讲前半段<b>只有这一条式子</b>。");

clearScene();setBig(null);
setEq("$$\\Delta w=\\alpha\\big(\\underbrace{\\ \\cdot\\ }_{\\text{target}}-x(s)^{\\top}w\\big)x(s)$$","top");
note("神谕不存在",640,310,"r lg");
note("这个槽填什么？",640,370,"y lg");
setCap("式子有了，但<b>真值那一格是空的</b> —— 神谕从来就不存在。");

clearScene();setEq(null);
setBig("三个目标 = 三个算法","各自有各自的推导和性质");
setCap("它们共用<b>同一条</b>更新式。差别<b>只在那一个槽</b>。");

clearScene();setBig(null);setEq(null);
note("真值（神谕）",340,250,"g lg","start");
note("回报 G_t",340,320,"b lg","start");
note("r + γ x(s′)ᵀw",340,390,"v lg","start");
setCap("三个填法：<b>真值</b>（只作对照）· <b>蒙特卡洛回报</b> · <b>自举的 TD 目标</b>。");

clearScene();setBig(null);setEq(null);
note("算期望",533,204,"y");
note("抽样",658,204,"y");
gridworld({rows:2,cols:2,cs:125,y:218,x:470,
  cls:function(i,j){return (i===0&&j===0)?"b":((i===0&&j===1)?"v":((i===1&&j===1)?"g":""));},
  val:function(i,j){return [["DP","TD"],["—","MC"]][i][j];}});
note("自举",448,278,"y","end");
note("不自举",448,403,"sm","end");
setCap("还是 L3 那两根轴。<b>函数逼近没有新增坐标</b>，它是在这张图<b>之外</b>加了一层。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:300,items:[
  {label:"一条更新式",sub:"误差 × 特征 × 步长",state:"on"},
  {label:"三个填法",sub:"真值 / G_t / 自举",state:"on"},
  {label:"差别继承自 L3",sub:"不必重新推导",state:"on"}]});
note("新东西只有一层投影",640,420,"y");
setCap("<b>指名反驳</b>：不是三个算法，是<b>一条式子三个填法</b>。");
